206:   private aplicarFiltrosAcceso() {
207:     if (this.loadingAcceso || !this.puedeAcceder) {
208:       return;
209:     }
210: 
211:     const proyectosPermitidos = this.IsAdmin
212:       ? [...this.proyectosFull]
213:       : this.proyectosFull.filter((proyecto: any) =>
214:           this.dependenciasUsuario.includes(Number(proyecto?.DependenciaId))
215:         );
216: 
217:     const facultadesPermitidasIds = Array.from(
218:       new Set(
219:         proyectosPermitidos
220:           .map((proyecto: any) => Number(proyecto?.FacultadId?.Id || proyecto?.FacultadId))
221:           .filter((id: number) => id > 0)
222:       )
223:     );
224: 
225:     this.facultades = this.IsAdmin
226:       ? [...this.facultadesFull]
227:       : this.facultadesFull.filter((facultad: any) =>
228:           facultadesPermitidasIds.includes(Number(facultad?.Id))
229:         );
230: 
231:     const facultadSeleccionada = Number(this.reporteForm.get('facultad')?.value || 0);
232:     this.proyectos = facultadSeleccionada
233:       ? proyectosPermitidos.filter((proyecto: any) =>
234:           Number(proyecto?.FacultadId?.Id || proyecto?.FacultadId) === facultadSeleccionada
235:         )
236:       : proyectosPermitidos;
237:   }
