246:   private filtrarProyectosPermitidosPorFacultad(idFacultad: number): any[] {
247:     const proyectosPermitidos = this.IsAdmin
248:       ? [...this.proyectosFull]
249:       : this.proyectosFull.filter((proyecto: any) =>
250:           this.dependenciasUsuario.includes(Number(proyecto?.DependenciaId))
251:         );
252: 
253:     return proyectosPermitidos.filter((proyecto: any) =>
254:       Number(proyecto?.FacultadId?.Id || proyecto?.FacultadId) === Number(idFacultad)
255:     );
256:   }
