258:   private normalizarListaRespuesta(response: any): any[] {
259:     if (Array.isArray(response)) {
260:       return response;
261:     }
262:     if (Array.isArray(response?.Data?.Data)) {
263:       return response.Data.Data;
264:     }
265:     if (Array.isArray(response?.Data)) {
266:       return response.Data;
267:     }
268:     return [];
269:   }
