308:   onReporteChange(event: any) {
309:     const eraGeneral = this.generalReport;
310:     if (event.value == 4) {
311:       this.caragarNivelesAcademicos()
312:       this.generalReport = true
313:       this.isTranferenciaOrReintegro = false
314:     } else if (event.value >= 5){
315:       this.isTranferenciaOrReintegro = true
316:       this.generalReport = false
317:     }else {
318:       this.isTranferenciaOrReintegro = false
319:       this.generalReport = false
320:     }
321:     if (eraGeneral !== this.generalReport) {
322:       this.limpiarSeleccionReporte();
323:       this.reporteForm.get('periodoAcademico')?.reset('');
324:     }
325:     // this.reporteForm.get('selectColumnas')?.setValue([])
326:     // this.columnas = this.tipoReporte[event.value - 1].Columnas
327:     this.columnas = (this.tipoReporte.find(r => r.Codigo === event.value)?.Columnas) || []
328:     // Se preseleccionan todas las columnas
329:     this.reporteForm.get('selectColumnas')?.setValue(this.columnas.map(c => c.Valor))
330:   }
