332:   downloadFile(base64: string, fileName: string) {
333:     const sliceSize = 512
334:     const byteCharacters = atob(base64);
335:     const byteArrays = [];
336:     for (let offset = 0; offset < byteCharacters.length; offset += sliceSize) {
337:       const slice = byteCharacters.slice(offset, offset + sliceSize);
338:       const byteNumbers = new Array(slice.length);
339:       for (let i = 0; i < slice.length; i++) {
340:         byteNumbers[i] = slice.charCodeAt(i);
341:       }
342:       const byteArray = new Uint8Array(byteNumbers);
343:       byteArrays.push(byteArray);
344:     }
345:     this.blobPdf = new Blob(byteArrays, { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
346:     saveAs(this.blobPdf, fileName);
347:   }
