349:   openDialog(): void {
350:     const byteCharacters = atob(this.reportePdf);
351:     const byteNumbers = new Array(byteCharacters.length);
352:     for (let i = 0; i < byteCharacters.length; i++) {
353:       byteNumbers[i] = byteCharacters.charCodeAt(i);
354:     }
355:     const byteArray = new Uint8Array(byteNumbers);
356:     const pdfBlob = new Blob([byteArray], { type: 'application/pdf' });
357:     this.reportePdfBlobUrl = window.URL.createObjectURL(pdfBlob);
358: 
359:     const dialogRef = this.dialog.open(ReporteVisualizerComponent, {
360:       width: '80vw',   // Set width to 60 percent of view port width
361:       height: '90vh',
362:       data: this.reportePdfBlobUrl
363:     });
364: 
365:     dialogRef.afterClosed().subscribe(result => {
366:       if (this.reportePdfBlobUrl) {
367:         window.URL.revokeObjectURL(this.reportePdfBlobUrl);
368:         this.reportePdfBlobUrl = "";
369:       }
370:     });
371:   }
